/* Shared, deterministic course tools. DeepSeek may call these; they also work without AI. */
(()=>{'use strict';const R=window.AGENT_KNOWLEDGE||[],byId=new Map(R.map(r=>[r.id,r]));
const clean=s=>String(s||'').toLowerCase().replace(/\s+/g,' ').trim();
function search(query,limit=3){const q=clean(query);if(!q)return R.slice(0,Math.min(13,limit));const terms=[...new Set([...(q.match(/[a-z][a-z0-9-]+/g)||[]),...Array.from({length:q.length-1},(_,i)=>q.slice(i,i+2)).filter(x=>/^[\u4e00-\u9fff]{2}$/.test(x))])];return R.map(r=>{const title=clean(r.title),keys=r.keywords.map(clean),all=clean([r.title,r.description,...r.facts].join(' '));let score=title.includes(q)?40:0;for(const k of keys)if(q.includes(k))score+=k.length>2?18:8;for(const t of terms){if(title.includes(t))score+=5;else if(keys.some(k=>k.includes(t)))score+=3;else if(all.includes(t))score++;}return {r,score};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,Math.max(1,Math.min(13,limit))).map(x=>x.r);}
function parseValues(text){const s=String(text||'').trim();if(!s)return [];const parts=s.split(/[\s,，、;；]+/);if(parts.some(v=>v===''||!/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[-+]?\d+)?$/i.test(v)))throw Error('请只输入数值，用逗号或空格分隔。');return parts.map(Number);}
function trial({values,baseline=500,alpha=.05,alternative='greater'}){if(!Array.isArray(values)||values.length<2||values.length>100||values.some(x=>typeof x!=='number'||!Number.isFinite(x)||Math.abs(x)>1e9))throw Error('请输入2至100个有限数值，每个数代表一个独立重复。');if(!Number.isFinite(baseline)||!Number.isFinite(alpha)||!(alpha>=.001&&alpha<=.2)||!['greater','less','two-sided'].includes(alternative))throw Error('请检查基准、显著性水平与检验方向。');const n=values.length,mean=values.reduce((a,b)=>a+b,0)/n,s=Math.sqrt(values.reduce((a,b)=>a+(b-mean)**2,0)/(n-1)),se=s/Math.sqrt(n);if(!(se>0))throw Error('这些重复完全相同，样本标准误差为0，不能据此完成常规t检验。');const t=(mean-baseline)/se,df=n-1,T=window.StudentTMath,cdf=T.cdf(t,df),p=alternative==='greater'?1-cdf:alternative==='less'?cdf:2*Math.min(cdf,1-cdf),critical=T.quantile(1-alpha/(alternative==='two-sided'?2:1),df),ciWidth=T.quantile(1-alpha/2,df)*se;return {values:values.slice(),baseline,alpha,alternative,n,mean,s,se,t,df,p,critical,significant:p<alpha,confidenceInterval:{level:1-alpha,lower:mean-ciWidth,upper:mean+ciWidth},assumptions:['各数对应独立的实验单位','按正态总体模型进行单样本t检验','基准与检验方向应事先确定'],scope:'比较与固定基准的差异；不能单凭此检验把差异全部归因于处理。'};}
function shift(r){return (R.findIndex(x=>x.id===r.id)+1)%r.practice.options.length;}
function practice(id){const r=byId.get(id)||search(id,1)[0]||byId.get('trial-story'),offset=shift(r);return {id:r.id+'-1',resourceId:r.id,question:r.practice.question,options:r.practice.options.slice(offset).concat(r.practice.options.slice(0,offset))};}
function grade(id,choice){const rid=String(id).replace(/-1$/,''),r=byId.get(rid);if(!r||!Number.isInteger(choice)||choice<0||choice>=r.practice.options.length)throw Error('没有找到这道题或所选答案。');const correct=(choice+shift(r))%r.practice.options.length===r.practice.correct;return {correct,hint:r.practice.hint,explanation:correct?r.practice.explanation:'',resourceId:rid};}
function resource(id){return byId.get(id)||null;}
function excerpt(r,query){const terms=r.keywords.filter(k=>clean(query).includes(clean(k))),parts=r.document.split(/\n\s*\n/),rank=parts.map((text,i)=>({text,score:terms.reduce((n,k)=>n+(text.includes(k)?3:0),0)+(i<2?1:0)}));return rank.sort((a,b)=>b.score-a.score).slice(0,5).map(x=>x.text).join('\n\n').slice(0,4200);}
window.PlantAgentTools={search,resource,parseValues,trial,practice,grade,excerpt,resources:R};
})();
